// Reproduce with: g++ -O3 -std=c++17 scripts/payout-jelly-v232-exact.cpp -o /tmp/jelly-v232-exact && /tmp/jelly-v232-exact
// All C(25,5) pouring sets and C(20,3) closing sets, including color-mix awards.
#include <bits/stdc++.h>
using namespace std;using U=uint32_t;
struct Pattern {string name;U seeds;long double sum=0,sq=0;uint64_t hist[13]={};};
int main(){vector<vector<int>> grids={{7,11,13,17},{6,8,16,18},{2,11,13,22},{5,9,15,19},{1,3,21,23},{0,4,20,24}};vector<Pattern> pats;for(int n=0;n<(int)grids.size();n++){U m=0;for(int i:grids[n])m|=1u<<i;pats.push_back({to_string(n),m});}vector<U> lines;for(int y=0;y<5;y++){U r=0,c=0;for(int x=0;x<5;x++){r|=1u<<(y*5+x);c|=1u<<(x*5+y);}lines.push_back(r);lines.push_back(c);}U diag=0,anti=0;for(int i=0;i<5;i++){diag|=1u<<(6*i);anti|=1u<<(4+4*i);}lines.push_back(diag);lines.push_back(anti);int pay[]={0,16,24,40,80,160,400,800,1600,4000,8000,0,30000};uint64_t N=0;for(int a=0;a<21;a++)for(int b=a+1;b<22;b++)for(int c=b+1;c<23;c++)for(int d=c+1;d<24;d++)for(int e=d+1;e<25;e++){int p[25];for(int i=0;i<25;i++)p[i]=i;auto find=[&](int v){while(p[v]!=v)v=p[v];return v;};auto join=[&](int x,int y){p[find(x)]=find(y);};U hits=0;for(int i:{a,b,c,d,e}){hits|=1u<<i;if(i%5)join(i,i-1);if(i%5<4)join(i,i+1);if(i>=5)join(i,i-5);if(i<20)join(i,i+5);}U masks[25]={},comps[25];vector<int> avail;for(int i=0;i<25;i++){masks[find(i)]|=1u<<i;if(!(hits>>i&1))avail.push_back(i);}for(int i=0;i<25;i++)comps[i]=masks[find(i)];vector<U> wets;for(auto &pat:pats){U wet=0;for(int i=0;i<25;i++)if(pat.seeds>>i&1)wet|=comps[i];wets.push_back(wet);}for(int x=0;x<18;x++)for(int y=x+1;y<19;y++)for(int z=y+1;z<20;z++){U A=comps[avail[x]],B=comps[avail[y]],C=comps[avail[z]];for(int k=0;k<(int)pats.size();k++){U wet=wets[k];int mix=0;if(wet&A)mix++;wet|=A;if(wet&B)mix++;wet|=B;if(wet&C)mix++;wet|=C;int n=0;for(U l:lines)if((wet&l)==l)n++;double w=pay[n]*(1+.5*mix);pats[k].sum+=w;pats[k].sq+=w*w;pats[k].hist[n]++;}N++;}}
 for(int k=0;k<(int)pats.size();k++){auto &p=pats[k];cout<<"{\"id\":"<<k<<",\"n\":"<<N<<",\"mean\":"<<setprecision(14)<<(double)(p.sum/N)<<",\"seeds\":[";for(int j=0;j<(int)grids[k].size();j++){if(j)cout<<",";cout<<grids[k][j];}cout<<"],\"hist\":[";for(int h=0;h<13;h++){if(h)cout<<",";cout<<p.hist[h];}cout<<"]}\n";}
}
